package model

import (
	"time"
)

// Alert represents a security alert generated by DPI analysis
type Alert struct {
	ID                  uint64    `json:"id"`
	Timestamp           time.Time `json:"timestamp"`
	Type                string    `json:"type"`
	SrcIP               string    `json:"src_ip"`
	DstIP               string    `json:"dst_ip"`
	SrcPort             uint16    `json:"src_port"`
	DstPort             uint16    `json:"dst_port"`
	Protocol            string    `json:"protocol"`
	Signature           string    `json:"signature"`
	Category            string    `json:"category"`
	Severity            uint8     `json:"severity"`
	Score               int       `json:"risk_score"`
	Status              string    `json:"status"`
	SensorID            string    `json:"sensor_id"`
	Domain              string    `json:"domain,omitempty"`
	SemanticFlowID      string    `json:"semantic_flow_id,omitempty"`
	SemanticSessionID   string    `json:"semantic_session_id,omitempty"`
	SemanticRiskScore   int       `json:"semantic_risk_score,omitempty"`
	SemanticRiskLevel   string    `json:"semantic_risk_level,omitempty"`
	SemanticContext     string    `json:"semantic_context,omitempty"`
	SemanticThreatType  string    `json:"semantic_threat_type,omitempty"`
}

// Severity levels
const (
	SeverityCritical = 1
	SeverityHigh     = 2
	SeverityMedium   = 3
	SeverityLow     = 4
)

// Alert types
const (
	AlertTypeDPI      = "dpi"
	AlertTypeLog      = "log"
	AlertTypeEndpoint = "endpoint"
)

// Alert categories
const (
	CategoryMining     = "mining"
	CategoryFraud      = "fraud"
	CategoryDGA        = "dga"
	CategoryDNSTunnel  = "dns_tunnel"
	CategorySuspicious = "suspicious"
	CategoryMalware    = "malware"
)

// Alert statuses
const (
	StatusNew     = "new"
	StatusHandled = "handled"
	StatusIgnored = "ignored"
)

// FromFlow creates an Alert from a FlowData
func (a *Alert) FromFlow(flow *FlowData) {
	a.Timestamp = time.Now()
	a.SrcIP = flow.SrcIP
	a.DstIP = flow.DstIP
	a.SrcPort = flow.SrcPort
	a.DstPort = flow.DstPort
	a.Protocol = flow.Protocol
	a.SensorID = flow.SensorID
	a.Domain = flow.GetDomain()
}

